printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s' '{"name":"read_file","arguments":{"path":"hello.txt"}}' > read.json
printf '%s' '{"name":"write_file","arguments":{"path":"notes.txt","text":"written over stdio\n"}}' > write.json
cat > session.jsonl <<'EOF'
{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"sh","version":"1"}}}
{"jsonrpc":"2.0","method":"notifications/initialized"}
{"jsonrpc":"2.0","id":2,"method":"ping"}
EOF
curl -d @read.json "mcp+stdio://localhost/surl?--directory&site&mcp+stdio:"
